package com.foodordering.notification; import com.foodordering.events.OrderCreatedEvent; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component class NotificationListener {private final NotificationRepository r;NotificationListener(NotificationRepository r){this.r=r;}@KafkaListener(topics="order-created",groupId="notification-group") void notify(OrderCreatedEvent e){String m="Your order #"+e.orderId()+" has been successfully placed.";r.save(Notification.make(e.orderId(),e.customerId(),m));System.out.println("[NOTIFICATION] "+m+" customerId="+e.customerId()+" amount="+e.totalAmount());}@KafkaListener(topics="order-created",groupId="analytics-group") void analytics(OrderCreatedEvent e){System.out.println("[ANALYTICS] order "+e.orderId()+" amount "+e.totalAmount());}}
